CREATE FUNCTION public.pe_save_intake(_queue uuid,_data jsonb,_submit boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q financial_document_review_queue; r jsonb; eid uuid; k text; BEGIN
SELECT * INTO q FROM financial_document_review_queue WHERE id=_queue FOR UPDATE;
IF q.id IS NULL OR q.entity_id<>'00000000-0000-4000-a000-000000000001'::uuid OR (q.created_by IS DISTINCT FROM auth.uid() AND NOT pe_finance_access(q.entity_id)) OR q.duplicate_of_document_id IS NOT NULL OR q.created_expense_id IS NOT NULL THEN RAISE EXCEPTION 'Receipt already linked'; END IF;
IF q.source_project_expense_id IS NOT NULL THEN RETURN jsonb_build_object('id',q.source_project_expense_id,'reused',true); END IF;
IF q.duplicate_of_id IS NOT NULL THEN SELECT * INTO q FROM financial_document_review_queue WHERE id=q.duplicate_of_id AND entity_id=q.entity_id FOR UPDATE; IF q.id IS NULL THEN RAISE EXCEPTION 'Receipt duplicate requires review'; END IF; IF q.source_project_expense_id IS NOT NULL THEN RETURN jsonb_build_object('id',q.source_project_expense_id,'reused',true); END IF; END IF;
k:=coalesce(q.file_sha256,'queue:'||q.id::text); r:=pe_action('save',_data||jsonb_build_object('intakeKey',k)); eid:=(r->>'id')::uuid; PERFORM pe_link_queue(q.id,eid); IF _submit AND (SELECT status FROM pm_expenses WHERE id=eid)='draft' THEN PERFORM pe_action('submit',jsonb_build_object('expenseId',eid)); END IF; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.pe_save_intake(uuid,jsonb,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pe_save_intake(uuid,jsonb,boolean) TO authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.pe_confirm_intake(uuid,uuid,jsonb)'::regprocedure) INTO d;
d:=pe_replace_once(d,' PERFORM set_config(''app.pe_action'',''1'',true);',' IF e.purchase_document_id IS NOT NULL AND q.created_expense_id=e.purchase_document_id AND q.source_project_expense_id=e.id THEN RETURN jsonb_build_object(''document_id'',e.purchase_document_id); END IF; PERFORM set_config(''app.pe_action'',''1'',true);');
d:=pe_replace_once(d,'payment_status=CASE WHEN e.payment_source_type=''personal'' THEN ''paid_at_source'' ELSE payment_status END,paid_method_unknown=', 'paid_from_card_id=CASE WHEN e.payment_source_type=''company_card'' THEN e.payment_card_id END,paid_from_account_id=CASE WHEN e.payment_source_type=''company_account'' THEN e.paid_from_account_id END,payment_status=CASE WHEN e.payment_source_type=''personal'' THEN ''paid_at_source'' ELSE payment_status END,paid_method_unknown='); EXECUTE d;
END $$;
CREATE FUNCTION public.pe_credit_document_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM project_expense_credit_allocations c JOIN financial_document_lines l ON l.id=c.credit_line_id WHERE l.document_id=OLD.id) AND (NEW.status,NEW.original_document_id,NEW.counterparty_client_id,NEW.entity_id,NEW.doc_type) IS DISTINCT FROM (OLD.status,OLD.original_document_id,OLD.counterparty_client_id,OLD.entity_id,OLD.doc_type) THEN RAISE EXCEPTION 'Expense credit documents are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pe_credit_document_guard BEFORE UPDATE ON public.financial_documents FOR EACH ROW EXECUTE FUNCTION public.pe_credit_document_guard();
